def is_not_prime(n):
    if n <= 1:
        return True
    if n <= 3:
        return False
    if n % 2 == 0 or n % 3 == 0:
        return True
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return True
        i += 6
    return False

import heapq

def heap_queue_largest(numbers, n):
    return heapq.nlargest(n, numbers)

def differ_At_One_Bit_Pos(a: int, b: int) -> bool:
    diff = a ^ b
    return diff != 0 and (diff & (diff - 1)) == 0

def find_Rotations(s: str) -> int:
    count = 0
    n = len(s)
    for i in range(1, n):
        rotated = s[i:] + s[:i]
        if rotated == s:
            count += 1
    return count

import re

def text_lowercase_underscore(text):
    return re.findall(r'[a-z]+', text)

def remove_dirty_chars(s: str, dirty_chars: str) -> str:
    dirty_set = set(dirty_chars)
    return ''.join(ch for ch in s if ch not in dirty_set)

def opposite_Signs(x, y):
    if x == 0 or y == 0:
        return False
    return (x < 0) != (y < 0)

def count_Substrings(s, sub):
    count = start = 0
    while True:
        start = s.find(sub, start)
        if start == -1:
            return count
        count += 1
        start += 1

def recursive_list_sum(lst):
    total = 0
    for item in lst:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def bell_number(n):
    """Return the Bell number for a set of size n (total number of partitions)."""
    bell = [[0] * (n+1) for _ in range(n+1)]
    bell[0][0] = 1
    for i in range(1, n+1):
        bell[i][0] = bell[i-1][i-1]
        for j in range(1, i+1):
            bell[i][j] = bell[i-1][j-1] + bell[i][j-1]
    return bell[n][0]

def is_Monotonic(arr):
    if not arr:
        return True
    increasing = decreasing = True
    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            decreasing = False
        if arr[i] < arr[i-1]:
            increasing = False
    return increasing or decreasing

def is_sublist(sub, main):
    if not sub:
        return True
    sub_len = len(sub)
    main_len = len(main)
    for i in range(main_len - sub_len + 1):
        if main[i:i+sub_len] == sub:
            return True
    return False

def get_equal(tuples):
    if not tuples:
        return True
    length = len(tuples[0])
    return all(len(t) == length for t in tuples)
